using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using Qms.Domain.InternalAudits;
namespace Qms.Infrastructure.Persistence.Configurations;
public sealed class InternalAuditConfiguration:IEntityTypeConfiguration<InternalAudit>{public void Configure(EntityTypeBuilder<InternalAudit>b){b.ToTable("internal_audit","internal_audit");b.HasKey(x=>x.Id);b.Property(x=>x.Title).HasMaxLength(240).IsRequired();b.Property(x=>x.AuditType).HasMaxLength(100).IsRequired();b.Property(x=>x.Scope).HasMaxLength(3000).IsRequired();b.Property(x=>x.Objectives).HasMaxLength(2000).IsRequired();b.Property(x=>x.Criteria).HasMaxLength(2000).IsRequired();b.Property(x=>x.AuditeeDepartment).HasMaxLength(160).IsRequired();b.Property(x=>x.LeadAuditor).HasMaxLength(200).IsRequired();b.Property(x=>x.LeadAuditorDepartment).HasMaxLength(160).IsRequired();b.Property(x=>x.UnplannedReason).HasMaxLength(2000);b.Property(x=>x.ChecklistVersion).HasMaxLength(80).IsRequired();b.Property(x=>x.Summary).HasMaxLength(3000);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(40);b.Property(x=>x.Version).IsConcurrencyToken();b.HasIndex(x=>x.QualityRecordId).IsUnique();b.HasIndex(x=>new{x.PlanYear,x.Status});b.HasOne<Qms.Domain.QualityRecords.QualityRecord>().WithMany().HasForeignKey(x=>x.QualityRecordId).OnDelete(DeleteBehavior.Restrict);b.HasMany(x=>x.Checklist).WithOne().HasForeignKey(x=>x.InternalAuditId).OnDelete(DeleteBehavior.Cascade);b.Navigation(x=>x.Checklist).UsePropertyAccessMode(PropertyAccessMode.Field);b.HasMany(x=>x.Findings).WithOne().HasForeignKey(x=>x.InternalAuditId).OnDelete(DeleteBehavior.Cascade);b.Navigation(x=>x.Findings).UsePropertyAccessMode(PropertyAccessMode.Field);}}
public sealed class AuditChecklistItemConfiguration:IEntityTypeConfiguration<AuditChecklistItem>{public void Configure(EntityTypeBuilder<AuditChecklistItem>b){b.ToTable("checklist_item","internal_audit");b.HasKey(x=>x.Id);b.Property(x=>x.Question).HasMaxLength(1000).IsRequired();b.Property(x=>x.Reference).HasMaxLength(300).IsRequired();b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.Evidence).HasMaxLength(3000);b.Property(x=>x.Note).HasMaxLength(2000);b.HasIndex(x=>new{x.InternalAuditId,x.Order}).IsUnique();}}
public sealed class AuditFindingConfiguration:IEntityTypeConfiguration<AuditFinding>{public void Configure(EntityTypeBuilder<AuditFinding>b){b.ToTable("finding","internal_audit");b.HasKey(x=>x.Id);b.Property(x=>x.Number).HasMaxLength(80).IsRequired();b.Property(x=>x.Title).HasMaxLength(240).IsRequired();b.Property(x=>x.Description).HasMaxLength(5000).IsRequired();b.Property(x=>x.RequirementReference).HasMaxLength(500).IsRequired();b.Property(x=>x.Classification).HasConversion<string>().HasMaxLength(30);b.Property(x=>x.Owner).HasMaxLength(200).IsRequired();b.Property(x=>x.Response).HasMaxLength(5000);b.Property(x=>x.CorrectiveAction).HasMaxLength(5000);b.Property(x=>x.VerificationNote).HasMaxLength(3000);b.Property(x=>x.Status).HasConversion<string>().HasMaxLength(30);b.HasIndex(x=>x.Number).IsUnique();b.HasOne<Qms.Domain.Capas.Capa>().WithMany().HasForeignKey(x=>x.LinkedCapaId).OnDelete(DeleteBehavior.Restrict);}}
